SELECT stddev(icustays.los) AS standard_deviation FROM patients JOIN admissions ON patients.subject_id = admissions.subject_id JOIN icustays ON admissions.stay_id = icustays.stay_id WHERE patients.gender = 'M' AND patients.anchor_age = 50 AND admissions.admission_type = 'H' AND icustays.intime <= '2018-06-01' AND icustays.outtime >= '2018-12-31' AND (SELECT COUNT(*) FROM diagnoses_icd WHERE diagnoses_icd.icd_code = '887.0' AND diagnoses_icd.icd_version = '2018' AND diagnoses_icd.seq_num = 1 AND diagnoses_icd.subject_id = patients.subject_id AND diagnoses_icd.hadm_id = admissions.hadm_id) > 0 AND (SELECT COUNT(*) FROM procedures_icd WHERE procedures_icd.icd_code = '887.0' AND procedures_icd.icd_version = '2018' AND procedures_icd.seq_num = 1 AND procedures_icd.subject_id = patients.subject_id AND procedures_icd.hadm_id = admissions.hadm_id) > 0;